function Document({text}:{text:string}){const blocks=text.split(/\n\s*\n/);return <div className="slr-document">{blocks.map((b,i)=>{if(b.startsWith('|')){const rows=b.split('\n').filter(x=>!/^\|[\s|:-]+\|?$/.test(x)).map(x=>x.split('|').slice(1,-1));return <div className="slr-table-scroll" key={i}><table><thead><tr>{rows[0]?.map((x,j)=><th key={j}><ReadingText text={x.replaceAll('**','')}/></th>)}</tr></thead><tbody>{rows.slice(1).map((r,k)=><tr key={k}>{r.map((x,j)=><td key={j}><ReadingText text={x.replaceAll('**','')}/></td>)}</tr>)}</tbody></table></div>;}if(b.startsWith('#'))return <h3 key={i}><ReadingText text={b.replace(/^#+\s*/,'')}/></h3>;return <p key={i}><ReadingText text={b.replaceAll('**','').replaceAll('`','')}/></p>;})}</div>;}
function RawTable({rows}:{rows:Row[]}){const [open,setOpen]=useState(false),[page,setPage]=useState(0);return <details onToggle={e=>setOpen(e.currentTarget.open)}><summary>View table ({rows.length} rows)</summary>{open&&<><div className="slr-table-scroll"><table><thead><tr>{Object.keys(rows[0]||{}).map(k=><th key={k}>{k}</th>)}</tr></thead><tbody>{rows.slice(page*25,page*25+25).map((r,i)=><tr key={i}>{Object.values(r).map((v,j)=><td key={j}>{v}</td>)}</tr>)}</tbody></table></div><div className="slr-row"><Button variant="outline" disabled={!page} onClick={()=>setPage(p=>p-1)}>Previous rows</Button><span>{page*25+1}–{Math.min((page+1)*25,rows.length)} of {rows.length}</span><Button variant="outline" disabled={(page+1)*25>=rows.length} onClick={()=>setPage(p=>p+1)}>Next rows</Button></div></>}</details>;}
function Field({name,hint,value,onChange}:{name:string;hint:string;value:string;onChange:(v:string)=>void}){return <label className="slr-field"><strong>{name}</strong><span>{hint}</span><Textarea rows={3} value={value} onChange={e=>onChange(e.target.value)}/></label>;}
function artifact(path:string){return '/api/synthesis/file?path='+encodeURIComponent(path);}
