 function resizePeek(width:number){const w=Math.round(Math.max(320,Math.min(width,document.documentElement.clientWidth-64)));setPeekWidth(w);setPeekExpanded(false);try{topicLocalStorage.setItem('atlas-peek-width',String(w));}catch{}}
 const reduceMotion=useReducedMotion();
