 useEffect(()=>{if(peek){panelBody.current?.scrollTo({top:panelScroll.current[peekStack.length]||0});panelBody.current?.closest('aside')?.querySelector<HTMLButtonElement>('[aria-label="Close reading panel"]')?.focus({preventScroll:true});}},[peek,peekStack.length]);
 useEffect(()=>{if(!peek)return;if(peekCollapsed)document.querySelector<HTMLButtonElement>('.atlas-peek-reopen')?.focus({preventScroll:true});else document.querySelector<HTMLButtonElement>('.atlas-reading-panel [aria-label="Close reading panel"]')?.focus({preventScroll:true});},[peekCollapsed]);
 useEffect(()=>{if(!peek)return;const escape=(event:KeyboardEvent)=>{if(event.defaultPrevented||(event.target as Element|null)?.closest?.('[role="dialog"]')||document.querySelector('[role="dialog"]'))return;if(event.key==='Escape'){setPeekStack([]);returnFocus.current?.focus({preventScroll:true});}};window.addEventListener('keydown',escape);return()=>window.removeEventListener('keydown',escape);},[peek]);
 const [stage,setStage]=useState('');
 const [movingIds,setMovingIds]=useState<string[]>([]);
 const [collectedPage,setCollectedPage]=useState(0);
 useEffect(()=>{if(!movingIds.length)return;const timer=setTimeout(()=>setMovingIds([]),320);return()=>clearTimeout(timer);},[movingIds]);
 
 const [data,setData]=useState<Dataset|null>(null),[state,setState]=useState<SlrState|null>(null),[version,setVersion]=useState(0),[tab,setTab]=useState('Evidence explorer'),[error,setError]=useState(''),[status,setStatus]=useState(''),[dirty,setDirty]=useState(false),[busy,setBusy]=useState(false);
 const [query,setQuery]=useState(''),[strand,setStrand]=useState(''),[construct,setConstruct]=useState(''),[type,setType]=useState(''),[record,setRecord]=useState(''),[page,setPage]=useState(0),[doc,setDoc]=useState('corpus_birdseye.md'),[section,setSection]=useState(sections[0][0]),[themeName,setThemeName]=useState(''),[paperLinks,setPaperLinks]=useState<Record<string,string>>({}),[workset,setWorkset]=useState('');
 useEffect(()=>{let alive=true;Promise.all([api<Dataset>('/synthesis'),api<{state:SlrState;version:number}>('/synthesis/workspace')]).then(([d,w])=>{if(!alive)return;setData(d);setState(w.state);setVersion(w.version);const recovered=topicLocalStorage.getItem('atlas-slr-recovery');if(recovered){try{const r=JSON.parse(recovered);if(r.version===w.version&&JSON.stringify(r.state)!==JSON.stringify(w.state)){setState(r.state);setDirty(true);setStatus('Recovered unsaved work from this browser. Save to keep it in Atlas.');}}catch{setStatus('Browser recovery could not be read. Your saved Atlas workspace is intact.');}}}).catch(e=>setError(e.message));return()=>{alive=false;};},[]);
 useEffect(()=>{let alive=true;const refresh=async()=>{try{const next=await api<Dataset>('/synthesis');if(alive)setData(current=>{if(!current||current.importedAt!==next.importedAt)return current;const before=current.statements.map(s=>s.claim_review||'').join('\n'),after=next.statements.map(s=>s.claim_review||'').join('\n');return before===after?current:next;});}catch{/* Preserve the displayed evidence and all unsaved notes during a transient service outage. */}};const timer=setInterval(refresh,30000);window.addEventListener('focus',refresh);return()=>{alive=false;clearInterval(timer);window.removeEventListener('focus',refresh);};},[]);
 useEffect(()=>{if(!data)return;let alive=true;Promise.all([api<{papers:PaperIdentity[]}>('/papers'),fetch('/synthesis-paper-links.json',{cache:'no-store'}).then(r=>r.ok?r.json() as Promise<SavedSourceLinks>:null).catch(()=>null)]).then(([inventory,saved])=>{if(!alive)return;const resolved=resolveSourceLinks(data,inventory.papers,saved);setPaperLinks(resolved.links);setSourceLinkIssues(resolved.issues);setSourceLinkFlags(resolved.flags);}).catch(e=>{if(alive){setPaperLinks({});setSourceLinkIssues(Object.fromEntries(data.records.map(r=>[r.record_id,'Paper inventory could not be loaded: '+e.message])));}});return()=>{alive=false;};},[data,linkRefresh]);
 useEffect(()=>{if(!dirty||!state)return;try{topicLocalStorage.setItem('atlas-slr-recovery',JSON.stringify({version,state}));}catch{/* Server save and export remain available when browser storage is full. */}const unload=(e:BeforeUnloadEvent)=>{e.preventDefault();};window.addEventListener('beforeunload',unload);return()=>window.removeEventListener('beforeunload',unload);},[state,dirty,version]);
 useEffect(()=>{currentState.current=state;},[state]);
