 useEffect(()=>{const receive=(event:Event)=>{const value=(event as CustomEvent<{state:SlrState;version:number}>).detail;if(!value?.state||!Number.isInteger(value.version))return;if(dirty){setStatus('Reader saved new evidence. Export unsaved changes before reloading this workspace.');return;}setState(value.state);setVersion(value.version);setStatus('Reader evidence and notes synced with saved workspace.');};window.addEventListener('atlas:reader-workspace-saved',receive);return()=>window.removeEventListener('atlas:reader-workspace-saved',receive);},[dirty]);
 function edit(next:SlrState){setState(next);setDirty(true);setStatus('Unsaved changes · browser recovery available');}
