 function jump(c='',s='',r=''){setConstruct(c);setStrand(s);setRecord(r);setQuery('');setType('');setWorkset('');setStage('');setPage(0);setTab('Evidence explorer');}
 if(!data||!state)return <section className="slr-root"><h1>Research workspace</h1>{error?<><p role="alert">{error}</p><Button variant="outline" onClick={()=>window.location.reload()}>Retry loading</Button></>:<p>Loading your research artifacts and saved workspace…</p>}</section>;
